package dev.phantom.ac;

import java.util.*;import static dev.phantom.ac.Maths.*;import static dev.phantom.ac.Packets.*;
/** Synthetic packet/timeline benchmark. It is a measurement harness, not a real-server performance claim. */
public final class Phase1PerformanceBenchmark { private Phase1PerformanceBenchmark(){} public record Result(long nanos,int events,int duplicates,int sequenceGaps,int outOfOrder,int serverTicks){} public static Result benchmark(int count){if(count<1)throw new IllegalArgumentException("count must be positive");List<RawPacket> raw=new ArrayList<>(count);for(int i=0;i<count;i++){raw.add(new RawPacket(i+1L,i*50_000_000L+(i%5)*1_000_000L,new Move(new Vec3(i*.01,64,i*.02),0f,0f,true,(long)i)));}Collections.reverse(raw);long begin=System.nanoTime();Timeline.Snapshot timeline=Timeline.assign(new Normalizer().normalize(raw),0,50_000_000L);long elapsed=System.nanoTime()-begin;Timeline.Integrity integrity=Timeline.inspect(timeline);int ticks=(int)timeline.events().stream().map(Timeline.Event::serverTick).distinct().count();return new Result(elapsed,integrity.events(),integrity.duplicatePackets(),integrity.sequenceGaps(),integrity.outOfOrderPackets(),ticks);}public static Result benchmark(){return benchmark(100_000);}}
